import { useState } from "react";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import { Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { toast } from "sonner";
import { useRequestChannel } from "@/hooks/useChannels";

const schema = z.object({
  url: z.string().url("Please enter a valid URL"),
  type: z.enum(["youtube", "podcast"]),
});

type FormData = z.infer<typeof schema>;

export function ChannelRequestForm() {
  const requestMutation = useRequestChannel();
  const [selectedType, setSelectedType] = useState<"youtube" | "podcast">(
    "youtube"
  );

  const {
    register,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm<FormData>({
    resolver: zodResolver(schema),
    defaultValues: { type: "youtube" },
  });

  const onSubmit = async (data: FormData) => {
    try {
      await requestMutation.mutateAsync({ type: data.type, url: data.url });
      toast.success("We'll review your channel request shortly.");
      reset();
    } catch {
      toast.error("Failed to submit request. Please try again.");
    }
  };

  const handleTypeChange = (type: "youtube" | "podcast") => {
    setSelectedType(type);
    setValue("type", type);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">Request a Channel</CardTitle>
        <CardDescription>
          Don't see a channel you want? Submit a request and we'll add it.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="space-y-2">
            <Label>Type</Label>
            <div className="flex gap-2">
              <Button
                type="button"
                size="sm"
                variant={selectedType === "youtube" ? "default" : "outline"}
                onClick={() => handleTypeChange("youtube")}
              >
                YouTube
              </Button>
              <Button
                type="button"
                size="sm"
                variant={selectedType === "podcast" ? "default" : "outline"}
                onClick={() => handleTypeChange("podcast")}
              >
                Podcast
              </Button>
            </div>
            <input type="hidden" {...register("type")} value={selectedType} />
          </div>

          <div className="space-y-2">
            <Label htmlFor="url">
              {selectedType === "youtube" ? "YouTube Channel URL" : "RSS Feed URL"}
            </Label>
            <Input
              id="url"
              type="url"
              placeholder={
                selectedType === "youtube"
                  ? "https://youtube.com/@channel"
                  : "https://example.com/feed.xml"
              }
              {...register("url")}
            />
            {errors.url && (
              <p className="text-sm text-destructive">{errors.url.message}</p>
            )}
          </div>

          <Button
            type="submit"
            className="w-full"
            disabled={requestMutation.isPending}
          >
            {requestMutation.isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              "Submit Request"
            )}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

