import { useState, useCallback } from "react";
import { useMutation } from "@tanstack/react-query";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ValidationProgress } from "./ValidationProgress";
import { useValidationPolling, isTerminalStatus } from "@/hooks/useValidationPolling";
import { adminApi } from "@/lib/api";
import { toast } from "sonner";

interface ApprovalModalProps {
  requestId: string;
  feedUrl: string;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export function ApprovalModal({
  requestId,
  feedUrl,
  open,
  onOpenChange,
  onSuccess,
}: ApprovalModalProps) {
  const [name, setName] = useState("");
  const [category, setCategory] = useState("");
  const [jobId, setJobId] = useState<string | null>(null);
  const [channelId, setChannelId] = useState<string | null>(null);
  const [approvalError, setApprovalError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [activationComplete, setActivationComplete] = useState(false);

  const { data: jobStatus } = useValidationPolling(jobId);

  // Mutation for activating the channel after validation completes
  const activationMutation = useMutation({
    mutationFn: (id: string) => adminApi.activateChannel(id),
    onSuccess: () => {
      setActivationComplete(true);
      toast.success("Channel approved and activated");
      setTimeout(() => {
        onOpenChange(false);
        onSuccess();
      }, 1500);
    },
    onError: () => {
      setApprovalError("Validation passed but activation failed");
    },
  });

  // Trigger activation when validation completes successfully
  const validationCompleted =
    jobStatus?.status === "completed" && channelId && !activationMutation.isPending;
  if (validationCompleted && !activationComplete && !activationMutation.isSuccess && !activationMutation.isError) {
    activationMutation.mutate(channelId);
  }

  // Compute display state from internal state
  const getDisplayState = (): "form" | "validating" | "success" | "error" => {
    if (activationComplete) return "success";
    if (approvalError || activationMutation.isError) return "error";
    if (jobStatus && isTerminalStatus(jobStatus.status) && jobStatus.status !== "completed") return "error";
    if (isSubmitting || jobId) return "validating";
    return "form";
  };

  const displayState = getDisplayState();
  const displayError = approvalError ||
    (jobStatus && isTerminalStatus(jobStatus.status) && jobStatus.status !== "completed"
      ? jobStatus.error || `Validation ${jobStatus.status}`
      : null);

  const resetModal = useCallback(() => {
    setName("");
    setCategory("");
    setJobId(null);
    setChannelId(null);
    setApprovalError(null);
    setIsSubmitting(false);
    setActivationComplete(false);
    activationMutation.reset();
  }, [activationMutation]);

  const handleOpenChange = useCallback(
    (newOpen: boolean) => {
      if (!newOpen) {
        resetModal();
      }
      onOpenChange(newOpen);
    },
    [onOpenChange, resetModal]
  );

  const handleSubmit = async () => {
    if (!name.trim()) {
      toast.error("Name is required");
      return;
    }

    setIsSubmitting(true);
    setApprovalError(null);

    try {
      // Create draft channel
      const approveResponse = await adminApi.approveRequest(requestId, {
        name,
        category: category || undefined,
      });
      const newChannelId = approveResponse.channel_id;
      setChannelId(newChannelId);

      // Start validation
      const validationResponse = await adminApi.startValidation(newChannelId);
      setJobId(validationResponse.job_id);
    } catch {
      setApprovalError("Failed to create channel");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleRetry = async () => {
    if (!channelId) return;

    setApprovalError(null);
    activationMutation.reset();

    try {
      const response = await adminApi.startValidation(channelId);
      setJobId(response.job_id);
    } catch {
      setApprovalError("Failed to restart validation");
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Approve Channel Request</DialogTitle>
        </DialogHeader>

        {displayState === "form" && (
          <>
            <div className="space-y-4">
              <div className="text-sm text-muted-foreground mb-2">URL: {feedUrl}</div>
              <div>
                <label className="text-sm font-medium" htmlFor="name">
                  Channel Name
                </label>
                <Input
                  id="name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="Enter channel name"
                  className="mt-1"
                />
              </div>
              <div>
                <label className="text-sm font-medium" htmlFor="category">
                  Category
                </label>
                <Input
                  id="category"
                  value={category}
                  onChange={(e) => setCategory(e.target.value)}
                  placeholder="e.g., Technology, Business"
                  className="mt-1"
                />
              </div>
            </div>
            <div className="flex justify-end gap-2 mt-4">
              <Button variant="outline" onClick={() => handleOpenChange(false)}>
                Cancel
              </Button>
              <Button onClick={handleSubmit}>Approve & Validate</Button>
            </div>
          </>
        )}

        {displayState === "validating" && jobStatus && (
          <>
            <div className="py-4">
              <ValidationProgress job={jobStatus} />
            </div>
            <div className="flex justify-end">
              <Button variant="outline" onClick={() => handleOpenChange(false)}>
                Close
              </Button>
            </div>
          </>
        )}

        {displayState === "validating" && !jobStatus && (
          <div className="py-4 text-center text-muted-foreground">
            Starting validation...
          </div>
        )}

        {displayState === "error" && (
          <>
            <div className="py-4">
              <p className="text-red-500 mb-4">{displayError}</p>
              {jobStatus && <ValidationProgress job={jobStatus} />}
            </div>
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={() => handleOpenChange(false)}>
                Close
              </Button>
              <Button onClick={handleRetry}>Retry Validation</Button>
            </div>
          </>
        )}

        {displayState === "success" && (
          <div className="py-4 text-center text-green-500">
            Channel approved and activated!
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

