import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { adminApi } from "@/lib/api";
import { useState } from "react";
import { Check, X } from "lucide-react";
import { ApprovalModal } from "@/components/admin/ApprovalModal";

export function AdminRequests() {
  const [page, setPage] = useState(1);
  const [statusFilter, setStatusFilter] = useState("pending");

  // Approval modal state
  const [approvalModal, setApprovalModal] = useState<{
    requestId: string;
    feedUrl: string;
  } | null>(null);

  const { data, isLoading, refetch } = useQuery({
    queryKey: ["admin-channel-requests", page, statusFilter],
    queryFn: () =>
      adminApi.getChannelRequests({
        page,
        status: statusFilter || undefined,
      }),
  });

  const handleReject = async (requestId: string) => {
    const notes = prompt("Enter rejection reason (optional):") || undefined;
    await adminApi.rejectRequest(requestId, { admin_notes: notes });
    refetch();
  };

  const getStatusVariant = (status: string) => {
    switch (status) {
      case "pending":
        return "secondary";
      case "approved":
        return "default";
      case "rejected":
        return "destructive";
      default:
        return "outline";
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Channel Requests</h2>
        <select
          className="border rounded px-3 py-2 text-sm"
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
        >
          <option value="">All Status</option>
          <option value="pending">Pending</option>
          <option value="approved">Approved</option>
          <option value="rejected">Rejected</option>
        </select>
      </div>

      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>User Email</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>URL</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Created</TableHead>
                <TableHead>Reviewed</TableHead>
                <TableHead></TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {isLoading ? (
                <TableRow>
                  <TableCell
                    colSpan={7}
                    className="text-center py-8 text-muted-foreground"
                  >
                    Loading...
                  </TableCell>
                </TableRow>
              ) : data?.items.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={7}
                    className="text-center py-8 text-muted-foreground"
                  >
                    No requests found
                  </TableCell>
                </TableRow>
              ) : (
                data?.items.map((request) => (
                  <TableRow key={request.request_id}>
                    <TableCell>{request.user_email}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{request.type}</Badge>
                    </TableCell>
                    <TableCell className="max-w-xs truncate">
                      <a
                        href={request.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-blue-600 hover:underline"
                      >
                        {request.url}
                      </a>
                    </TableCell>
                    <TableCell>
                      <Badge variant={getStatusVariant(request.status)}>
                        {request.status}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {new Date(request.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      {request.reviewed_at
                        ? new Date(request.reviewed_at).toLocaleDateString()
                        : "-"}
                    </TableCell>
                    <TableCell>
                      {request.status === "pending" && (
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() =>
                              setApprovalModal({
                                requestId: request.request_id,
                                feedUrl: request.url,
                              })
                            }
                            className="text-green-600 hover:text-green-700"
                          >
                            <Check className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleReject(request.request_id)}
                            className="text-red-600 hover:text-red-700"
                          >
                            <X className="h-4 w-4" />
                          </Button>
                        </div>
                      )}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {data && data.pages > 1 && (
        <div className="flex justify-center gap-2">
          <Button
            variant="outline"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
          >
            Previous
          </Button>
          <span className="py-2">
            Page {page} of {data.pages}
          </span>
          <Button
            variant="outline"
            disabled={page >= data.pages}
            onClick={() => setPage((p) => p + 1)}
          >
            Next
          </Button>
        </div>
      )}

      {approvalModal && (
        <ApprovalModal
          requestId={approvalModal.requestId}
          feedUrl={approvalModal.feedUrl}
          open={!!approvalModal}
          onOpenChange={(open) => !open && setApprovalModal(null)}
          onSuccess={() => {
            setApprovalModal(null);
            refetch();
          }}
        />
      )}
    </div>
  );
}

