import { useState } from "react";
import { Check, Loader2, Podcast, Youtube } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { toast } from "sonner";
import { useSubscribe } from "@/hooks/useSubscriptions";
import type { Channel, Subscription } from "@/lib/types";

function formatRelativeDate(dateString: string | null): string | null {
  if (!dateString) return null;
  const date = new Date(dateString);
  const now = new Date();
  const diffMs = now.getTime() - date.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays === 0) return "today";
  if (diffDays === 1) return "yesterday";
  if (diffDays < 7) return `${diffDays} days ago`;
  if (diffDays < 30) {
    const weeks = Math.floor(diffDays / 7);
    return `${weeks} week${weeks > 1 ? "s" : ""} ago`;
  }
  if (diffDays < 365) {
    const months = Math.floor(diffDays / 30);
    return `${months} month${months > 1 ? "s" : ""} ago`;
  }
  return date.toLocaleDateString();
}

interface ChannelCardProps {
  channel: Channel;
  subscription?: Subscription;
}

export function ChannelCard({ channel, subscription }: ChannelCardProps) {
  const subscribeMutation = useSubscribe();
  const [isSubscribed, setIsSubscribed] = useState(!!subscription);

  const handleSubscribe = async () => {
    try {
      await subscribeMutation.mutateAsync(channel.channel_id);
      setIsSubscribed(true);
      toast.success(`You're now subscribed to ${channel.name}`);
    } catch {
      toast.error("Failed to subscribe. Please try again.");
    }
  };

  const lastEpisode = formatRelativeDate(channel.last_episode_at);
  const TypeIcon = channel.type === "youtube" ? Youtube : Podcast;

  return (
    <Card>
      <CardHeader className="flex flex-row items-start justify-between space-y-0 gap-4">
        <div className="flex items-center gap-3 min-w-0 flex-1">
          <Avatar className="h-12 w-12 rounded-lg shrink-0">
            <AvatarImage src={channel.image_url ?? undefined} alt={channel.name} />
            <AvatarFallback className="rounded-lg bg-muted">
              <TypeIcon className="h-6 w-6 text-muted-foreground" />
            </AvatarFallback>
          </Avatar>
          <div className="space-y-1 min-w-0">
            <CardTitle className="text-base truncate">{channel.name}</CardTitle>
            <CardDescription className="line-clamp-1">
              {channel.description || `${channel.type} channel`}
            </CardDescription>
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <span className="capitalize">{channel.type}</span>
              {channel.episode_count > 0 && (
                <>
                  <span className="text-muted-foreground/50">&middot;</span>
                  <span>{channel.episode_count} episode{channel.episode_count !== 1 ? "s" : ""}</span>
                </>
              )}
              {lastEpisode && (
                <>
                  <span className="text-muted-foreground/50">&middot;</span>
                  <span>Updated {lastEpisode}</span>
                </>
              )}
            </div>
          </div>
        </div>
        <Button
          size="sm"
          variant={isSubscribed ? "secondary" : "default"}
          disabled={isSubscribed || subscribeMutation.isPending}
          onClick={handleSubscribe}
          className="shrink-0"
        >
          {subscribeMutation.isPending ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : isSubscribed ? (
            <>
              <Check className="h-4 w-4 mr-1" />
              Subscribed
            </>
          ) : (
            "Subscribe"
          )}
        </Button>
      </CardHeader>
    </Card>
  );
}

