// Auth types
export interface User {
  email: string;
  expires_at: string;
  is_admin: boolean;
}

export interface RequestLinkResponse {
  message: string;
}

export interface VerifyResponse {
  email: string;
  expires_at: string;
  is_admin: boolean;
}

// Channel types
export interface Channel {
  channel_id: string;
  type: string;
  name: string;
  description: string | null;
  category: string | null;
  image_url: string | null;
  last_episode_at: string | null;
  listen_url: string | null;
  episode_count: number;
}

export interface ChannelListResponse {
  channels: Channel[];
  total: number;
}

// Subscription types
export interface Subscription {
  subscription_id: string;
  channel_id: string;
  channel_name: string;
  channel_type: string;
  backfill_limit: number;
  created_at: string;
  image_url: string | null;
  last_episode_at: string | null;
  listen_url: string | null;
  episode_count: number;
}

export interface SubscriptionListResponse {
  subscriptions: Subscription[];
  total: number;
}

export interface CreateSubscriptionResponse {
  subscription_id: string;
  message: string;
}

// Channel request types
export interface ChannelRequestResponse {
  request_id: string;
  status: string;
  message: string;
}

export interface MyChannelRequest {
  request_id: string;
  type: string;
  url: string;
  status: "pending" | "approved" | "rejected";
  rejection_reason: string | null;
  created_at: string;
  reviewed_at: string | null;
  queue_position: number | null;
}

// Episode types
export interface Episode {
  episode_id: string;
  title: string | null;
  published_at: string | null;
  duration_seconds: number | null;
  description: string | null;
  status: "sent" | "pending" | "available";
  queue_position: number | null;
  next_batch_at: string | null;
  estimated_ready_at: string | null;
}

export interface EpisodeListResponse {
  episodes: Episode[];
  total: number;
  page: number;
  per_page: number;
}

export interface RequestEpisodeResponse {
  queued: boolean;
  message: string;
}

export interface BackfillResponse {
  episodes_queued: number;
  message: string;
}

// Summary types
export interface SummaryResponse {
  episode_id: string;
  title: string | null;
  published_at: string | null;
  channel_name: string;
  summary: string;
  model_id: string;
  prompt_version: string;
}

export interface ResendResponse {
  sent: boolean;
  message: string;
}

// User usage types
export interface UsageResponse {
  tier: string;
  is_admin: boolean;
  max_subscriptions: number | null;
  max_requests_per_month: number | null;
  backfill_depth: number;
  can_resend_email: boolean;
  subscriptions_count: number;
  episode_requests_this_month: number;
}

// Summary preferences types
export interface SummaryPreferences {
  format?: "bullets" | "paragraphs" | "detailed";
  length?: "short" | "medium" | "long";
  include_timestamps?: boolean;
  include_quotes?: boolean;
}

export interface UpdatePreferencesRequest {
  preferences: SummaryPreferences;
}

export interface UpdatePreferencesResponse {
  preferences: SummaryPreferences;
  message: string;
}

// API Error
export class ApiError extends Error {
  status: number;
  data: { detail: string };

  constructor(status: number, data: { detail: string }) {
    super(data.detail || `API Error: ${status}`);
    this.name = "ApiError";
    this.status = status;
    this.data = data;
  }
}

// Admin types
export interface AdminDashboardStats {
  pending_count: number;
  processing_count: number;
  sent_24h_count: number;
  failed_count: number;
  oldest_pending_hours: number | null;
  gpu_fail_loops: number;
  last_poller_run: string | null;
  last_controller_run: string | null;
  last_processor_run: string | null;
  db_connected: boolean;
  // Cookie health
  cookie_status: "healthy" | "warning" | "expired";
  cookie_last_success: string | null;
  cookie_consecutive_failures: number;
}

export interface AdminErrorSummary {
  message: string;
  count: number;
  last_seen: string;
}

export interface AdminDashboardErrors {
  errors: AdminErrorSummary[];
  total_failed_24h: number;
}

export interface AdminPaginatedResponse<T> {
  items: T[];
  total: number;
  page: number;
  page_size: number;
  pages: number;
}

export interface AdminUserSummary {
  user_id: string;
  email: string;
  tier: string;
  is_admin: boolean;
  created_at: string;
  subscription_count: number;
  sent_delivery_count: number;
}

// Channel status enum
export type ChannelStatus = 'draft' | 'active' | 'inactive';

export interface AdminChannelSummary {
  channel_id: string;
  name: string;
  type: string;
  category: string | null;
  is_active: boolean;
  status: ChannelStatus;
  last_validated_at: string | null;
  subscriber_count: number;
  episode_count: number;
  transcribed_count: number;
  summarized_count: number;
  last_episode_at: string | null;
  created_at: string | null;
}

export interface AdminChannelDetail {
  channel_id: string;
  name: string;
  type: string;
  category: string | null;
  description: string | null;
  image_url: string | null;
  listen_url: string | null;
  youtube_channel_id: string | null;
  youtube_playlist_id: string | null;
  rss_feed_url: string | null;
  is_active: boolean;
  subscriber_count: number;
  episode_count: number;
  last_episode_at: string | null;
  created_at: string | null;
}

export interface AdminChannelRequestSummary {
  request_id: string;
  user_email: string;
  type: string;
  url: string;
  status: string;
  created_at: string;
  reviewed_at: string | null;
}

export interface AdminDeliverySummary {
  delivery_id: string;
  episode_title: string | null;
  channel_name: string;
  user_email: string;
  status: string;
  attempts: number;
  last_error: string | null;
  created_at: string;
  sent_at: string | null;
}

export interface AdminEpisodeSummary {
  episode_id: string;
  title: string | null;
  channel_name: string;
  source_type: string;
  published_at: string | null;
  has_transcript: boolean;
  has_summary: boolean;
  created_at: string;
}

export interface AdminProcessingStats {
  episodes_processed: number;
  success_rate: number;
  avg_processing_minutes: number;
  transcript_sources: Record<string, number>;
  llm_models: Record<string, number>;
  transcript_cache_hits: number;
  summary_cache_hits: number;
}

// Validation stage status
export interface ValidationStage {
  status: 'pending' | 'running' | 'success' | 'failed';
  duration_ms?: number;
  error?: string;
}

// Extended stage types with stage-specific data
export interface DiscoveryStage extends ValidationStage {
  episodes_found?: number;
  new_episodes?: number;
}

export interface EpisodeStage extends ValidationStage {
  episode_id?: string;
  title?: string;
}

export interface ProcessingStage extends ValidationStage {
  transcript_source?: string;
}

export interface EmailStage extends ValidationStage {
  sent_to?: string;
}

// Full validation job status
export interface ValidationJobStatus {
  job_id: string;
  channel_id: string;
  channel_name: string;
  status: 'pending' | 'running' | 'completed' | 'failed' | 'timed_out' | 'cancelled';
  current_stage?: string;
  created_at: string;
  completed_at?: string;
  total_duration_ms?: number;
  failed_stage?: string;
  error?: string;
  stages?: {
    discovery?: DiscoveryStage;
    episode?: EpisodeStage;
    processing?: ProcessingStage;
    email?: EmailStage;
  };
}

// Response from starting validation
export interface ValidationJobCreated {
  job_id: string;
  channel_id: string;
  channel_name: string;
  status: string;
  created_at: string;
}

content.text:
## Design Section 2: State Management & Results

**Filter State:**
- Three pieces of local state in `Channels.tsx`: `searchQuery`, `typeFilter`, `categoryFilter`
- No URL persistence (keeps it simple - filters reset on page refresh)
- No debouncing needed for search (filtering a small list is instant)

**Filtering Logic:**
```typescript
const filteredChannels = channels.filter(channel => {
  const matchesSearch = channel.name.toLowerCase().includes(searchQuery.toLowerCase());
  const matchesType = typeFilter === 'all' || channel.type === typeFilter;
  const matchesCategory = categoryFilter === 'all' || channel.category === categoryFilter;
  return matchesSearch && matchesType && matchesCategory;
});
```

**Results Feedback:**
- Show count above list: "Showing 12 of 45 channels" (only when filtered)
- When no results match: "No channels match your filters" with a "Clear filters" button

**Category List:**
- Extracted dynamically from loaded channels: `[...new Set(channels.map(c => c.category).filter(Boolean))]`
- Sorted alphabetically
- Null/empty categories excluded from dropdown

---

Does this approach look right?

## Design Section 3: Component Structure

**File changes:**

1. **`frontend/src/pages/Channels.tsx`** - Add filter state and filtering logic, render filter bar
2. **`frontend/src/components/features/ChannelFilters.tsx`** (new) - Filter bar component

**ChannelFilters props:**
```typescript
interface ChannelFiltersProps {
  searchQuery: string;
  onSearchChange: (query: string) => void;
  typeFilter: string;
  onTypeChange: (type: string) => void;
  categoryFilter: string;
  onCategoryChange: (category: string) => void;
  categories: string[];  // Available categories from data
}
```

**UI Components used:**
- `Input` from shadcn/ui (search field)
- `Select` from shadcn/ui (dropdowns)
- `Search` icon from lucide-react

**No new dependencies** - everything uses existing shadcn/ui components.

---

That's the complete design. Does this look good, or any adjustments?

