import { useMemo, useState } from "react";
import { PageContainer } from "@/components/layout";
import { ChannelCard } from "@/components/features/ChannelCard";
import { ChannelFilters } from "@/components/features/ChannelFilters";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { useChannels } from "@/hooks/useChannels";
import { useSubscriptions } from "@/hooks/useSubscriptions";

export function Channels() {
  const { data: channelsData, isLoading: channelsLoading } = useChannels();
  const { data: subscriptionsData, isLoading: subscriptionsLoading } =
    useSubscriptions();

  // Filter state
  const [searchQuery, setSearchQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState("all");

  const isLoading = channelsLoading || subscriptionsLoading;

  // Create a map of channel_id -> subscription for quick lookup
  const subscriptionMap = new Map(
    subscriptionsData?.subscriptions.map((s) => [s.channel_id, s]) || []
  );

  // Extract unique categories from channels
  const categories = useMemo(() => {
    if (!channelsData?.channels) return [];
    const cats = channelsData.channels
      .map((c) => c.category)
      .filter((c): c is string => Boolean(c));
    return [...new Set(cats)].sort();
  }, [channelsData?.channels]);

  // Filter channels
  const filteredChannels = useMemo(() => {
    if (!channelsData?.channels) return [];
