import { useMemo, useState } from "react";
import { PageContainer } from "@/components/layout";
import { ChannelCard } from "@/components/features/ChannelCard";
import { ChannelFilters } from "@/components/features/ChannelFilters";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { useChannels } from "@/hooks/useChannels";
import { useSubscriptions } from "@/hooks/useSubscriptions";

export function Channels() {
  const { data: channelsData, isLoading: channelsLoading } = useChannels();
  const { data: subscriptionsData, isLoading: subscriptionsLoading } =
    useSubscriptions();

  // Filter state
  const [searchQuery, setSearchQuery] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState("all");

  const isLoading = channelsLoading || subscriptionsLoading;

  // Create a map of channel_id -> subscription for quick lookup
  const subscriptionMap = new Map(
    subscriptionsData?.subscriptions.map((s) => [s.channel_id, s]) || []
  );

  // Extract unique categories from channels
  const categories = useMemo(() => {
    if (!channelsData?.channels) return [];
    const cats = channelsData.channels
      .map((c) => c.category)
      .filter((c): c is string => Boolean(c));
    return [...new Set(cats)].sort();
  }, [channelsData?.channels]);

  // Filter channels
  const filteredChannels = useMemo(() => {
    if (!channelsData?.channels) return [];
    return channelsData.channels.filter((channel) => {
      const matchesSearch = channel.name
        .toLowerCase()
        .includes(searchQuery.toLowerCase());
      const matchesType = typeFilter === "all" || channel.type === typeFilter;
      const matchesCategory =
        categoryFilter === "all" || channel.category === categoryFilter;
      return matchesSearch && matchesType && matchesCategory;
    });
  }, [channelsData?.channels, searchQuery, typeFilter, categoryFilter]);

  const isFiltered =
    searchQuery !== "" || typeFilter !== "all" || categoryFilter !== "all";

  const clearFilters = () => {
    setSearchQuery("");
    setTypeFilter("all");
    setCategoryFilter("all");
  };

  return (
    <PageContainer>
      <div className="space-y-6">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">Channels</h1>
          <p className="text-muted-foreground">
            Browse and subscribe to podcasts and YouTube channels
          </p>
        </div>

        {!isLoading && channelsData && channelsData.channels.length > 0 && (
          <ChannelFilters
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            typeFilter={typeFilter}
            onTypeChange={setTypeFilter}
            categoryFilter={categoryFilter}
            onCategoryChange={setCategoryFilter}
            categories={categories}
          />
        )}

        {isLoading ? (
          <div className="space-y-4">
            {[...Array(4)].map((_, i) => (
              <Skeleton key={i} className="h-24 w-full" />
            ))}
          </div>
        ) : channelsData?.channels.length === 0 ? (
          <p className="text-muted-foreground text-center py-8">
            No channels available yet.
          </p>
        ) : filteredChannels.length === 0 ? (
          <div className="text-center py-8 space-y-3">
            <p className="text-muted-foreground">
              No channels match your filters.
            </p>
            <Button variant="outline" size="sm" onClick={clearFilters}>
              Clear filters
            </Button>
          </div>
        ) : (
          <div className="space-y-4">
            {isFiltered && (
              <p className="text-sm text-muted-foreground">
                Showing {filteredChannels.length} of {channelsData?.total}{" "}
                channels
              </p>
            )}
            {filteredChannels.map((channel) => (
              <ChannelCard
                key={channel.channel_id}
                channel={channel}
                subscription={subscriptionMap.get(channel.channel_id)}
              />
            ))}
          </div>
        )}
      </div>
    </PageContainer>
  );
}

